import catalogJson from "../../content/sources.json";
import type { CatalogSource, SourceRef } from "./types";

/** Public catalog of citable books (facts only), generated by scripts/build_source_catalog.py. */
export const CATALOG: Record<string, CatalogSource> = (catalogJson as { sources: Record<string, CatalogSource> }).sources;

/** Printed page number for a physical PDF page, or null when the book prints none there. */
export function printedPage(src: CatalogSource, physical: number): number | null {
  if (src.page_label_offset == null || src.page_label_from == null || physical < src.page_label_from) return null;
  return physical - src.page_label_offset;
}

/** "pp. 40–42" using the book's printed numbers where it has them, else "PDF pp. 54–56". */
export function pageRange(src: CatalogSource, [a, b]: [number, number]): string {
  const pa = printedPage(src, a), pb = printedPage(src, b);
  const [x, y, prefix] = pa != null && pb != null ? [pa, pb, ""] : [a, b, "PDF "];
  return x === y ? `${prefix}p. ${x}` : `${prefix}pp. ${x}–${y}`;
}

export interface Citation {
  id: string;
  book: string;
  title: string;
  authors: string;
  section: string;
  pages: string;
  license: string;
  licenseUrl: string;
  url: string;
  /** Deep link to the cited section, for web sources. */
  sectionUrl?: string;
  adapted: boolean;
}

export function cite(ref: SourceRef, catalog: Record<string, CatalogSource> = CATALOG): Citation | null {
  const src = catalog[ref.source_id];
  if (!src) return null; // the build gate rejects this; never crash the page over it
  const web = src.kind === "web";
  const anchor = web ? src.anchors?.[String(ref.pages[0])] : undefined;
  return {
    id: ref.id, book: src.short, title: src.title, authors: src.authors.join(", "), section: ref.section,
    pages: web ? "online" : pageRange(src, ref.pages), license: src.license, licenseUrl: src.license_url,
    url: src.official_url, sectionUrl: anchor ? `${src.official_url}#${anchor}` : undefined,
    adapted: ref.use === "adapted",
  };
}
